import torch
import torch.nn as nn
import hashlib
from torch.utils.cpp_extension import load_inline

_STARK_EXTENSION = None

def _stark_strip_anchor_markers(source: str) -> str:
    cleaned_lines = []
    for line in source.splitlines():
        stripped = line.lstrip()
        if stripped.startswith('# <<<IMPROVE:') or stripped.startswith('# <<<END_IMPROVE>>>'):
            continue
        cleaned_lines.append(line)
    return '\n'.join(cleaned_lines)

def _stark_extension_name() -> str:
    digest = hashlib.sha1((_stark_strip_anchor_markers(CUDA_CPP_SRC) + _stark_strip_anchor_markers(CUDA_CU_SRC)).encode('utf-8')).hexdigest()[:12]
    return f'stark_cuda_l2_p60_{digest}'

def _stark_get_extension():
    global _STARK_EXTENSION
    if _STARK_EXTENSION is None:
        _STARK_EXTENSION = load_inline(
            name=_stark_extension_name(),
            cpp_sources=_stark_strip_anchor_markers(CUDA_CPP_SRC),
            cuda_sources=_stark_strip_anchor_markers(CUDA_CU_SRC),
            functions=None,
            extra_cflags=['-O3'],
            extra_cuda_cflags=['-O3', '--use_fast_math'],
            with_cuda=True,
            verbose=False,
        )
    return _STARK_EXTENSION

# <<<IMPROVE:user_helpers>>>
# <<<END_IMPROVE>>>

CUDA_CPP_SRC = r"""
# <<<IMPROVE:cuda_cpp>>>
#include <torch/extension.h>

torch::Tensor swish_groupnorm_hardswish_cuda(
    torch::Tensor x,
    torch::Tensor weight,
    torch::Tensor bias,
    int64_t num_groups,
    double eps
);

PYBIND11_MODULE(TORCH_EXTENSION_NAME, m) {
    m.def("swish_groupnorm_hardswish", &swish_groupnorm_hardswish_cuda,
          "Fused Swish + GroupNorm + HardSwish (CUDA)");
}
# <<<END_IMPROVE>>>
"""

CUDA_CU_SRC = r"""
# <<<IMPROVE:cuda_cu>>>
#include <torch/extension.h>
#include <cuda.h>
#include <cuda_runtime.h>

// Fused kernel: Swish -> GroupNorm -> HardSwish
// Layout: x is NCDHW, contiguous, float32
// One block per (n, g) pair; two-pass reduction in shared memory.
__global__ void __launch_bounds__(256, 4)
swish_groupnorm_hardswish_kernel(
    const float* __restrict__ x,
    const float* __restrict__ weight,
    const float* __restrict__ bias,
    float* __restrict__ out,
    int N, int C, int D, int H, int W,
    int num_groups,
    float eps
) {
    int n = blockIdx.x;
    int g = blockIdx.y;
    int channels_per_group = C / num_groups;
    int spatial = D * H * W;
    int elements_per_group = channels_per_group * spatial;

    // Base offset in the flattened NCDHW tensor for (n, g)
    int64_t base = (int64_t)n * C * spatial + (int64_t)g * channels_per_group * spatial;

    extern __shared__ float smem[];
    float* ssum   = smem;
    float* ssumsq = smem + blockDim.x;

    // Pass 1: compute sum and sum-of-squares of Swish(x) over this group
    float local_sum= 0.0f;
    float local_sum_sq = 0.0f;

    for (int i = threadIdx.x; i < elements_per_group; i += blockDim.x) {
        int c_local = i / spatial;
        int s       = i - c_local * spatial;
        int64_t idx = base + (int64_t)c_local * spatial + s;
        float v  = __ldg(x + idx);
        float sv = v * (1.0f / (1.0f + __expf(-v)));  // Swish
        local_sum    += sv;
        local_sum_sq += sv * sv;
    }

    ssum[threadIdx.x]= local_sum;
    ssumsq[threadIdx.x] = local_sum_sq;
    __syncthreads();

    // Block reduction (blockDim.x must be power-of-2)
    for (int stride = blockDim.x >> 1; stride > 0; stride >>= 1) {
        if (threadIdx.x < stride) {
            ssum[threadIdx.x]   += ssum[threadIdx.x + stride];
            ssumsq[threadIdx.x] += ssumsq[threadIdx.x + stride];
        }
        __syncthreads();
    }

    float inv_n= 1.0f / (float)elements_per_group;
    float mean    = ssum[0] * inv_n;
    float var     = ssumsq[0] * inv_n - mean * mean;
    float inv_std = rsqrtf(var + eps);

    // Pass 2: apply affine GroupNorm then HardSwish and write output
    for (int i = threadIdx.x; i < elements_per_group; i += blockDim.x) {
        int c_local = i / spatial;
        int s       = i - c_local * spatial;
        int c= g * channels_per_group + c_local;
        int64_t idx = base + (int64_t)c_local * spatial + s;

        float v  = __ldg(x + idx);
        float sv = v * (1.0f / (1.0f + __expf(-v)));  // Swish (recomputed)

        float normed = (sv - mean) * inv_std;
        float y      = normed * __ldg(weight + c) + __ldg(bias + c);

        // HardSwish: 0 if y<=-3, y if y>=3, else y*(y+3)/6
        float hs;
        if (y <= -3.0f) {
            hs = 0.0f;
        } else if (y >= 3.0f) {
            hs = y;
        } else {
            hs = y * (y + 3.0f) * (1.0f / 6.0f);
        }
        out[idx] = hs;
    }
}

torch::Tensor swish_groupnorm_hardswish_cuda(
    torch::Tensor x,
    torch::Tensor weight,
    torch::Tensor bias,
    int64_t num_groups,
    double eps
) {
    TORCH_CHECK(x.is_cuda(), "x must be a CUDA tensor");
    TORCH_CHECK(x.is_contiguous(), "x must be contiguous");
    TORCH_CHECK(x.dim() == 5, "x must be 5-dimensional (N,C,D,H,W)");
    TORCH_CHECK(x.scalar_type() == torch::kFloat, "x must be float32");

    int N = (int)x.size(0);
    int C = (int)x.size(1);
    int D = (int)x.size(2);
    int H = (int)x.size(3);
    int W = (int)x.size(4);

TORCH_CHECK(C % num_groups == 0, "C must be divisible by num_groups");

    auto out = torch::empty_like(x);

    const int block_size = 256;
    dim3 grid((unsigned)N, (unsigned)num_groups);
    dim3 block(block_size);
    size_t smem_bytes = 2 * block_size * sizeof(float);

    swish_groupnorm_hardswish_kernel<<<grid, block, smem_bytes>>>(
        x.data_ptr<float>(),
        weight.data_ptr<float>(),
        bias.data_ptr<float>(),
        out.data_ptr<float>(),
        N, C, D, H, W,
        (int)num_groups,
        (float)eps
    );

    return out;
}
# <<<END_IMPROVE>>>
"""

class ModelNew(nn.Module):
    """
        Model that performs a 3D transposed convolution, applies Swish activation, 
        group normalization, and then HardSwish activation.
        """
    def __init__(self, in_channels, out_channels, kernel_size, stride, padding, groups, eps, bias=True):
        super().__init__()
        # <<<IMPROVE:init_body>>>
        self.conv_transpose = nn.ConvTranspose3d(in_channels, out_channels, kernel_size, stride=stride, padding=padding, bias=bias)
        self.group_norm = nn.GroupNorm(num_groups=groups, num_channels=out_channels, eps=eps)
        # <<<END_IMPROVE>>>

    def forward(self, x):
        # <<<IMPROVE:forward_stmt_1>>>
        # Baseline fallback keeps the official PyTorch forward path.
        # After implementing CUDA_CPP_SRC / CUDA_CU_SRC, call _stark_get_extension().your_entrypoint(...).
        x = self.conv_transpose(x)
        # <<<END_IMPROVE>>>
        # <<<IMPROVE:forward_stmt_2>>>
        x = _stark_get_extension().swish_groupnorm_hardswish(
                    x,
                    self.group_norm.weight,
                    self.group_norm.bias,
                    self.group_norm.num_groups,
                    float(self.group_norm.eps)
                )
        # <<<END_IMPROVE>>>
        # <<<IMPROVE:forward_stmt_3>>>
        # GroupNorm fused into swish_groupnorm_hardswish extension above
        # <<<END_IMPROVE>>>
        # <<<IMPROVE:forward_stmt_4>>>
        # HardSwish fused into swish_groupnorm_hardswish extension above
        # <<<END_IMPROVE>>>
        # <<<IMPROVE:forward_stmt_5>>>
        return x
        # <<<END_IMPROVE>>>

