        warp_sumsqs[warp_id] = local_sum_sq;
    }
    __syncthreads();

    float group_sum    = 0.0f;
    float group_sum_sq = 0.0f;
    if (threadIdx.x < 4) {
        group_sum    = warp_sums[threadIdx.x];
        group_sum_sq = warp_sumsqs[threadIdx.x];
    }
    for (int offset = 2; offset > 0; offset >>= 1) {
        group_sum    += __shfl_down_sync(0xf, group_sum,    offset);
        group_sum_sq += __shfl_down_sync(0xf, group_sum_sq, offset);
    }
    if (threadIdx.x == 0) {
        warp_sums[0]   = group_sum;
        warp_sumsqs[0] = group_sum_sq;
    }
    __syncthreads();

    int elements_per_group = 4 * spatial;
    float inv_n   = 1.0f / (float)elements_per_group;
    float mean    = warp_sums[0] * inv_n;
    float var     = warp_sumsqs[0] * inv_n - mean * mean;
    float inv_std = rsqrtf(var + eps);

    int g4 = g * 4;
    float w0 = __ldg(weight + g4),     b0 = __ldg(bias + g4);
    float w1 = __ldg(weight + g4 + 1), b1 = __ldg(bias + g4 + 1);
    float w2 = __ldg(weight + g4 + 2), b2 = __ldg(bias + g4 + 2);
    float w3 = __ldg(weight + g4 + 3), b3 = __ldg(bias + g4 + 3);

    // Writeback pass: float4 load, compute, float4 store per channel
    for (int c_local = 0; c_local < 4; c_local++) {
        int64_t ch_off = base + (int64_t)c_local * spatial;
        const float4* xv  = reinterpret_cast<const float4*>(x   + ch_off);
        float4*       outv= reinterpret_cast<float4*>      (out + ch_off);
        float wc, bc;
        if      (c_local == 0) { wc = w0; bc = b0; }
        else if (c_local == 1) { wc = w1; bc = b1; }
        else if (c_local == 2) { wc = w2; bc = b2; }
        else                   { wc = w3; bc = b3; }

        for (int s4 = threadIdx.x; s4 < spatial4; s4 += 128) {
            float4 v4 = __ldg(xv + s4);
            float sv0 = v4.x * (1.0f / (1.0f + __expf(-v4.x)));
            float sv1 = v4.y * (1.0f / (1.0f + __expf(-v4.y)));
            float sv2 = v4.z * (1.0f / (1.0f + __expf(-v4.z)));
            float sv3 = v4.w * (1.0f / (1.0f + __expf(-v4.w)));

            float y0 = (sv0 - mean) * inv_std * wc + bc;
            float y1 = (sv1 - mean) * inv_std * wc + bc;
            float y2 = (sv2 - mean) * inv_std * wc + bc;
            float y3 = (sv3 - mean) * inv_std * wc + bc;

            float4 res;
            res.x = (y0 <= -3.0f) ? 0.0f : (y0 >= 3.0f ? y0 : y0 * (y0 + 3.0f) * (1.0f/6.0f));
            res.y = (y1 <= -3.0f) ? 0.0f : (y1 >= 3.0f ? y1 : y1 * (y1 + 3.0f) * (1.0f/6.0f));
            res.z = (y2 <= -3.0f) ? 0.0f : (y2 >= 3.0f ? y2 : y2 * (y2 + 3.0f) * (1.0f/6.0f));
            res.w = (y3 <= -3.0f) ? 0.0f : (y3 >= 3.0f ? y3 : y3 * (y3 + 3.0f) * (1.0f/6.0f));
            outv[s4] = res;
        }
    }
}

// Scalar specialized kernel for C=16, num_groups=4, spatial not divisible by 4
__global__ void __launch_bounds__(128, 4)
swish_groupnorm_hardswish_specialized_cpg4(
    const float* __restrict__ x,
    const float* __restrict__ weight,
    const float* __restrict__ bias,
    float* __restrict__ out,
    int N, int D, int H, int W,
    float eps
) {
    int n = blockIdx.x;
    int g = blockIdx.y;
    int spatial = D * H * W;
    int64_t base = ((int64_t)n * 16 + (int64_t)g * 4) * spatial;

    __shared__ float warp_sums[4];
    __shared__ float warp_sumsqs[4];

    float local_sum    = 0.0f;
    float local_sum_sq = 0.0f;

    int64_t ch_base0 = base;
    int64_t ch_base1 = base + (int64_t)spatial;
    int64_t ch_base2 = base + (int64_t)2 * spatial;
    int64_t ch_base3 = base + (int64_t)3 * spatial;

    for (int s = threadIdx.x; s < spatial; s += 128) {
        float v0 = __ldg(x + ch_base0 + s);
        float sv0 = v0 * (1.0f / (1.0f + __expf(-v0)));
        local_sum += sv0; local_sum_sq += sv0 * sv0;

        float v1 = __ldg(x + ch_base1 + s);
        float sv1 = v1 * (1.0f / (1.0f + __expf(-v1)));
        local_sum += sv1; local_sum_sq += sv1 * sv1;

        float v2 = __ldg(x + ch_base2 + s);
        float sv2 = v2 * (1.0f / (1.0f + __expf(-v2)));
        local_sum += sv2; local_sum_sq += sv2 * sv2;

        float v3 = __ldg(x + ch_base3 + s);
        float sv3 = v3 * (1.0f / (1.0f + __expf(-v3)));
        local_sum += sv3; local_sum_sq += sv3 * sv3;
    }

    int lane    = threadIdx.x & 31;
    int warp_id = threadIdx.x >> 5;
    for (int offset = 16; offset > 0; offset >>= 1) {
        local_sum    += __shfl_down_sync(0xffffffff, local_sum,    offset);
        local_sum_sq += __shfl_down_sync(0xffffffff, local_sum_sq, offset);
    }
    if (lane == 0) {
        warp_sums[warp_id]   = local_sum;
        warp_sumsqs[warp_id] = local_sum_sq;
    }
    __syncthreads();

    float group_sum = 0.0f, group_sum_sq = 0.0f;
    if (threadIdx.x < 4) {
        group_sum    = warp_sums[threadIdx.x];
        group_sum_sq = warp_sumsqs[threadIdx.x];
    }
    for (int offset = 2; offset > 0; offset >>= 1) {
        group_sum    += __shfl_down_sync(0xf, group_sum,    offset);
        group_sum_sq += __shfl_down_sync(0xf, group_sum_sq, offset);
    }
    if (threadIdx.x == 0) {
        warp_sums[0]   = group_sum;
        warp_sumsqs[0] = group_sum_sq;
    }
    __syncthreads();

    int elements_per_group = 4 * spatial;
    float inv_n   = 1.0f / (float)elements_per_group;
    float mean    = warp_sums[0] * inv_n;
    float var     = warp_sumsqs[0] * inv_n - mean * mean;
    float inv_std = rsqrtf(var + eps);

    int g4 = g * 4;
    float w0 = __ldg(weight + g4),     b0 = __ldg(bias + g4);
    float w1 = __ldg(weight + g4 + 1), b1 = __ldg(bias + g4 + 1);
    float w2 = __ldg(weight + g4 + 2), b2 = __ldg(bias + g4 + 2);
    float w3 = __ldg(weight + g4 + 3), b3 = __ldg(bias + g4 + 3);

    for (int s = threadIdx.x; s < spatial; s += 128) {
        float v0 = __ldg(x + ch_base0 + s);
        float sv0 = v0 * (1.0f / (1.0f + __expf(-v0)));
        float y0 = (sv0 - mean) * inv_std * w0 + b0;
        out[ch_base0 + s] = (y0 <= -3.0f) ? 0.0f : (y0 >= 3.0f ? y0 : y0 * (y0 + 3.0f) * (1.0f/6.0f));

        float v1 = __ldg(x + ch_base1 + s);
        float sv1 = v1 * (1.0f / (1.0f + __expf(-v1)));
        float y1 = (sv1 - mean) * inv_std * w1 + b1;
        out[ch_base1 + s] = (y1 <= -3.0f) ? 0.0f : (y1 >= 3.0f ? y1 : y1 * (y1 + 3.0f) * (1.0f/6.0f));

        float v2 = __ldg(x + ch_base2 + s);
        float sv2 = v2 * (1.0f / (1.0f + __expf(-v2)));
        float y2 = (sv2 - mean) * inv_std * w2 + b2;
        out[ch_base2 + s] = (y2 <= -3.0f) ? 0.0f : (y2 >= 3.0f ? y2 : y2 * (y2 + 3.0f) * (1.0f/6.0f));

        float v3 = __ldg(x + ch_base3 + s);
        float sv3 = v3 * (1.0f / (1.0f + __expf(-v3)));
        float y3 = (sv3 - mean) * inv_std * w3 + b3;
        out[ch_base3 + s] = (y3 <= -3.0f) ? 0.0f : (y3 >= 3.0f ? y3 : y3 * (y3 + 3.0f) * (1.0f/6.0f));
    }
}

// Generic fallback kernel for arbitrary C and num_groups
__global__ void __launch_bounds__(256, 4)
swish_groupnorm_hardswish_generic(
    const float* __restrict__ x,
    const float* __restrict__ weight,
    const float* __restrict__ bias,
    float* __restrict__ out,
    int N, int C, int D, int H, int W,
    int num_groups,
    float eps
) {
    int n = blockIdx.x;
    int g = blockIdx.y;
    int channels_per_group = C / num_groups;
    int spatial = D * H * W;
    int elements_per_group = channels_per_group * spatial;

    int64_t base = (int64_t)n * C * spatial + (int64_t)g * channels_per_group * spatial;

    extern __shared__ float smem[];
    float* ssum   = smem;
    float* ssumsq = smem + blockDim.x;

    float local_sum    = 0.0f;
    float local_sum_sq = 0.0f;

    for (int i = threadIdx.x; i < elements_per_group; i += blockDim.x) {
        int c_local = i / spatial;
        int s       = i - c_local * spatial;
        int64_t idx = base + (int64_t)c_local * spatial + s;
        float v  = __ldg(x + idx);
        float sv = v * (1.0f / (1.0f + __expf(-v)));
        local_sum    += sv;
        local_sum_sq += sv * sv;
    }

    ssum[threadIdx.x]   = local_sum;
    ssumsq[threadIdx.x] = local_sum_sq;
    __syncthreads();

    for (int stride = blockDim.x >> 1; stride > 0; stride >>= 1) {
        if (threadIdx.x < stride) {
            ssum[threadIdx.x]   += ssum[threadIdx.x + stride];
            ssumsq[threadIdx.x] += ssumsq[threadIdx.x + stride];
        }
        __syncthreads();
    }

    float inv_n   = 1.0f / (float)elements_per_group;
    float mean    = ssum[0] * inv_n;
    float var     = ssumsq[0] * inv_n - mean * mean;
    float inv_std = rsqrtf(var + eps);

    for (int i = threadIdx.x; i < elements_per_group; i += blockDim.x) {
        int c_local = i / spatial;
        int s       = i - c_local * spatial;
        int c       = g * channels_per_group + c_local;
        int64_t idx = base + (int64_t)c_local * spatial + s;

        float v  = __ldg(x + idx);
        float sv = v * (1.0f / (1.0f + __expf(-v)));
        float normed = (sv - mean) * inv_std;
        float y = normed * __ldg(weight + c) + __ldg(bias + c);

        float hs;
        if      (y <= -3.0f) hs = 0.0f;
        else if (y >=  3.0f) hs = y;
        else                 hs = y * (y + 3.0f) * (1.0f / 6.0f);

        out[idx] = hs;
    }
}

torch::Tensor swish_groupnorm_hardswish_cuda(
    torch::Tensor x,
    torch::Tensor weight,
    torch::Tensor bias,
    int64_t num_groups,
    double eps
) {
    TORCH_CHECK(x.is_cuda(),       "x must be a CUDA tensor");
    TORCH_CHECK(x.is_contiguous(), "x must be contiguous");
    TORCH_CHECK(x.dim() == 5,      "x must be 5-dimensional (N,C,D,H,W)");
    TORCH_CHECK(x.scalar_type() == torch::kFloat, "x must be float32");

    int N = (int)x.size(0);
    int C = (int)x.size(1);
    int D = (int)x.size(2);
    int H = (int)x.size(3);
    int W = (int)x.size(4);

    TORCH_CHECK(C % num_groups == 0, "C must be divisible by num_groups");

    auto out = torch::empty_like(x);
    dim3 grid((unsigned)N, (unsigned)num_groups);

    if (C == 16 && num_groups == 4) {
        int spatial = D * H * W;
        if ((spatial & 3) == 0) {
            // float4 vectorized path: spatial divisible by 4, pointers naturally aligned
            swish_groupnorm_hardswish_specialized_cpg4_vec4<<<grid, 128>>>(
                x.data_ptr<float>(),
                weight.data_ptr<float>(),
                bias.data_ptr<float>(),
                out.data_ptr<float>(),
                N, D, H, W,
                (float)eps
            );
        } else {
            swish_groupnorm_hardswish_specialized_cpg4<<<grid, 128>>>(
                x.data_ptr<float>(),
                weight.data_ptr<float>(),
                bias.data_ptr<float>(),
                out.data_ptr<float>(),
                N, D, H, W,
                (float)eps
            );
        }
    } else {
        const int block_size = 256;
        size_t smem_bytes = 2 * block_size * sizeof(float);
        swish_groupnorm_hardswish_generic<<<grid, block_size, smem_bytes>>>(
            x.data_ptr<float>(),
            weight.data_ptr<float>(),
            bias.data_ptr<float>(),
            out.data_ptr<float>(),
            N, C, D, H, W,
            (int)num_groups,
            (float)eps
        );
    }

    return out;
}
